namespace Scheduling;

/// <summary>Places jobs onto the most suitable available resource.</summary>
public sealed class Scheduler
{
    private const int MaximumCalendarEntries = 20;
    private const int OvertimeCalendarThreshold = 10;
    private const int OvertimePriorityThreshold = 5;
    private const int UrgentPriorityThreshold = 8;
    private const double MaximumRegularHours = 8;

    public IReadOnlyList<string> PlaceJobs(IEnumerable<Job> jobs, IReadOnlyList<Resource> resources)
    {
        var placements = new List<string>();

        foreach (var job in jobs)
        {
            if (!string.IsNullOrEmpty(job.RequiredSkill))
                placements.Add(CreatePlacement(job, resources));
        }

        return placements;
    }

    private static string CreatePlacement(Job job, IReadOnlyList<Resource> resources)
    {
        var resource = FindBestResource(job.RequiredSkill, resources);
        if (resource is null)
            return $"{job.Id}:UNPLACED";

        return FormatPlacement(job, resource);
    }

    private static Resource? FindBestResource(
        string requiredSkill,
        IReadOnlyList<Resource> resources)
    {
        Resource? chosen = null;

        foreach (var resource in resources)
        {
            if (!IsEligible(resource, requiredSkill))
                continue;

            if (chosen is null || resource.Calendar.Count < chosen.Calendar.Count)
                chosen = resource;
        }

        return chosen;
    }

    private static bool IsEligible(Resource resource, string requiredSkill) =>
        resource.Skills.Contains(requiredSkill) &&
        resource.Calendar.Count <= MaximumCalendarEntries;

    private static string FormatPlacement(Job job, Resource resource)
    {
        var suffix = RequiresOvertime(job, resource)
            ? ":OT"
            : job.Priority > UrgentPriorityThreshold
                ? ":URGENT"
                : string.Empty;

        return $"{job.Id}:{resource.Name}{suffix}";
    }

    private static bool RequiresOvertime(Job job, Resource resource) =>
        (job.Priority > OvertimePriorityThreshold &&
         resource.Calendar.Count > OvertimeCalendarThreshold) ||
        job.Duration.TotalHours > MaximumRegularHours;
}
